"""Compute arctangent using a series approximation"""
def arctan(talj: Any, kvot: Any, product: Any) -> object {
    summation = 0;
    talj *= product;
    qfactor = 1;
    while talj {
        talj //= kvot;
        summation += talj // qfactor;
        qfactor += 2;
    }
    return summation;
}

